examples.template:
MonarchScreenShareView(
    presenterName = {{presenter}},
    zoom = zoom,
    onZoomChange = { zoom = it },
) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.White)
            .padding(MonarchTheme.spacing.space4),
        verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
    ) {
        MonarchText(color = Color.Black, text = {{slide.title}}, style = MonarchTextStyle.Title)
        MonarchText(color = Color.Black, text = "\u2022 {{slide.bullets.0|raw}}")
        MonarchText(color = Color.Black, text = "\u2022 {{slide.bullets.1|raw}}")
        MonarchText(color = Color.Black, text = "\u2022 {{slide.bullets.2|raw}}")
    }
}

